using System.Collections.Concurrent;
using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly ConcurrentDictionary<string, string> _notes = new();
    private readonly HttpClient _httpClient;

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyDictionary<string, string> Notes => _notes;

    [Description("Search the web for information on a given query. Returns a list of search result snippets with titles and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("User-Agent", "ResearchAgent/1.0");

        try
        {
            using var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var results = ParseDuckDuckGoLiteResults(html);

            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note with a key and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short descriptive key for the note (e.g., 'definition', 'key_findings')")] string key,
        [Description("The content of the note")] string content)
    {
        _notes[key] = content;
        return $"Note saved with key '{key}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieve a previously saved research note by its key.")]
    public string GetNote(
        [Description("The key of the note to retrieve")] string key)
    {
        return _notes.TryGetValue(key, out var content)
            ? content
            : $"No note found with key '{key}'. Available keys: {string.Join(", ", _notes.Keys)}";
    }

    [Description("List all saved research note keys and a preview of their content.")]
    public string ListNotes()
    {
        if (_notes.IsEmpty)
        {
            return "No notes saved yet.";
        }

        var entries = _notes.Select(kvp =>
        {
            var preview = kvp.Value.Length > 100
                ? string.Concat(kvp.Value.AsSpan(0, 100), "...")
                : kvp.Value;
            return $"- {kvp.Key}: {preview}";
        });

        return string.Join('\n', entries);
    }

    private static List<SearchResult> ParseDuckDuckGoLiteResults(string html)
    {
        var results = new List<SearchResult>();

        // Parse result snippets from DuckDuckGo Lite HTML
        var span = html.AsSpan();
        const string linkMarker = "class=\"result-link\"";

        var pos = 0;
        while (pos < span.Length && results.Count < 5)
        {
            var linkIdx = html.IndexOf(linkMarker, pos, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            // Extract URL from href
            var hrefStart = html.LastIndexOf("href=\"", linkIdx, Math.Min(linkIdx, 200), StringComparison.Ordinal);
            string url = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                {
                    url = html[hrefStart..hrefEnd];
                }
            }

            // Extract link text as title
            var tagEnd = html.IndexOf('>', linkIdx);
            if (tagEnd < 0) break;
            var closeTag = html.IndexOf("</a>", tagEnd, StringComparison.Ordinal);
            var title = closeTag > tagEnd
                ? StripHtml(html[(tagEnd + 1)..closeTag]).Trim()
                : "";

            // Extract snippet from the next result-snippet class
            var snippet = "";
            var snippetMarker = html.IndexOf("class=\"result-snippet\"", closeTag > 0 ? closeTag : linkIdx + linkMarker.Length, StringComparison.Ordinal);
            if (snippetMarker >= 0)
            {
                var snippetStart = html.IndexOf('>', snippetMarker);
                if (snippetStart >= 0)
                {
                    var snippetEnd = html.IndexOf("</td>", snippetStart, StringComparison.Ordinal);
                    if (snippetEnd < 0) snippetEnd = html.IndexOf("</span>", snippetStart, StringComparison.Ordinal);
                    if (snippetEnd > snippetStart)
                    {
                        snippet = StripHtml(html[(snippetStart + 1)..snippetEnd]).Trim();
                    }
                }
            }

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(title, url, snippet));
            }

            pos = linkIdx + linkMarker.Length;
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var result = new System.Text.StringBuilder(html.Length);
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) result.Append(c);
        }
        return WebUtility.HtmlDecode(result.ToString());
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

