using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient through the MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Set up tools ---
using var httpClient = new HttpClient();
var researchTools = new ResearchTools(httpClient);

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNote),
    AIFunctionFactory.Create(researchTools.ListNotes),
};

// --- Create the agent with Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this workflow:
        1. Break the topic into 2-3 specific search queries.
        2. Search the web for each query using the SearchWebAsync tool.
        3. Save important findings as notes using the SaveNote tool (use descriptive keys).
        4. After gathering enough information, list your notes with ListNotes.
        5. Synthesize all findings into a well-structured summary with:
           - An overview paragraph
           - Key findings as bullet points
           - Sources referenced

        Be thorough but concise. Always cite where information came from.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and organizing findings.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MAF)          ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "";
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.WriteLine("No topic provided. Exiting.");
        return;
    }
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var session = await agent.CreateSessionAsync();

await foreach (var update in agent.RunStreamingAsync(
    $"Research this topic thoroughly: {topic}",
    session,
    runOptions))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

// --- Display collected notes ---
if (researchTools.Notes.Count > 0)
{
    Console.WriteLine("\n── Saved Research Notes ──");
    foreach (var (key, value) in researchTools.Notes)
    {
        Console.WriteLine($"\n[{key}]");
        Console.WriteLine(value.Length > 300 ? string.Concat(value.AsSpan(0, 300), "...") : value);
    }
}

